ALTER POLICY "user can read own memberships and farm co-members" ON "farm_members" TO "authenticated" USING ((("farm_members"."user_id" = (select auth.uid())) or ("farm_members"."farm_id" = (select farm_id()))));--> statement-breakpoint
ALTER POLICY "members of same farm can read each others profile and owners can read their own profile" ON "profiles" TO "authenticated" USING (((EXISTS (SELECT 1 FROM farm_members WHERE farm_id = (select farm_id()) AND user_id = "profiles"."id")) or ((select auth.uid()) = "profiles"."id")));--> statement-breakpoint
ALTER POLICY "submitter can update own draft change requests" ON "wiki_change_requests" TO "authenticated" USING ((("wiki_change_requests"."submitted_by" = (select auth.uid())) and ("wiki_change_requests"."status"::text in ('draft', 'changes_requested')))) WITH CHECK ("wiki_change_requests"."submitted_by" = (select auth.uid()));